package com.angle.trading.security;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.security.core.Authentication;import org.springframework.security.web.authentication.AuthenticationSuccessHandler;import org.springframework.stereotype.Component;import jakarta.servlet.ServletException;import jakarta.servlet.http.*;import java.io.IOException;@Componentpublic class CustomAuthenticationSuccessHandler implements AuthenticationSuccessHandler {    private static final Logger log =            LoggerFactory.getLogger(CustomAuthenticationSuccessHandler.class);    @Override    public void onAuthenticationSuccess(HttpServletRequest request,                                        HttpServletResponse response,                                        Authentication authentication)            throws IOException, ServletException {        log.info("Login Success : {}", authentication.getName());        response.sendRedirect("/dashboard");    }}